"#ifndef DOWNLOADER_HPP
#define DOWNLOADER_HPP

#include <string>
#include <vector>
#include <thread>
#include <atomic>
#include <functional>
#include <chrono>

namespace DownloaderCore {

struct DownloadChunk {
    size_t id;
    uint64_t startByte;
    uint64_t endByte;
    uint64_t downloadedBytes;
    bool completed;
    bool failed;
};

struct DownloadProgress {
    uint64_t totalBytes;
    uint64_t downloadedBytes;
    double speedBytesPerSec;
    double progressPercent;
    uint32_t activeThreads;
};

using ProgressCallback = std::function<void(const DownloadProgress&)>;

class NativeDownloader {
public:
    NativeDownloader(const std::string& url, const std::string& outputPath, size_t threadCount = 8);
    ~NativeDownloader();

    bool start();
    void pause();
    void resume();
    void cancel();

    void setProgressCallback(ProgressCallback callback) { progressCb = callback; }
    DownloadProgress getProgress() const;
    bool isFinished() const { return isComplete.load(); }

private:
    std::string mediaUrl;
    std::string outputFile;
    size_t numThreads;

    uint64_t fileSize;
    bool supportsRange;

    std::vector<DownloadChunk> chunks;
    std::vector<std::thread> workerThreads;

    std::atomic<bool> isRunning;
    std::atomic<bool> isPaused;
    std::atomic<bool> isComplete;
    std::atomic<uint64_t> totalDownloaded;

    ProgressCallback progressCb;

    bool queryFileInfo();
    void downloadSegmentWorker(size_t chunkId);
    void updateProgressLoop();
};

} // namespace DownloaderCore

#endif // DOWNLOADER_HPP
"

"#include "downloader.hpp"
#include <windows.h>
#include <wininet.h>
#include <iostream>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <algorithm>

#pragma comment(lib, "wininet.lib")

namespace DownloaderCore {

NativeDownloader::NativeDownloader(const std::string& url, const std::string& outputPath, size_t threadCount)
    : mediaUrl(url), outputFile(outputPath), numThreads(threadCount),
      fileSize(0), supportsRange(false), isRunning(false), isPaused(false),
      isComplete(false), totalDownloaded(0) {}

NativeDownloader::~NativeDownloader() {
    cancel();
}

bool NativeDownloader::queryFileInfo() {
    HINTERNET hInternet = InternetOpenA("DownloaderEngine/1.0", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (!hInternet) return false;

    HINTERNET hUrl = InternetOpenUrlA(hInternet, mediaUrl.c_str(), NULL, 0,
                                     INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_RELOAD | INTERNET_FLAG_SECURE, 0);
    if (!hUrl) {
        // Try non-secure if HTTPS failed or flag issue
        hUrl = InternetOpenUrlA(hInternet, mediaUrl.c_str(), NULL, 0, INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_RELOAD, 0);
    }

    if (!hUrl) {
        InternetCloseHandle(hInternet);
        return false;
    }

    char buffer[256];
    DWORD bufferLen = sizeof(buffer);
    DWORD index = 0;

    // Check Content-Length
    if (HttpQueryInfoA(hUrl, HTTP_QUERY_CONTENT_LENGTH, buffer, &bufferLen, &index)) {
        fileSize = std::stoull(buffer);
    } else {
        fileSize = 0;
    }

    // Check Accept-Ranges
    bufferLen = sizeof(buffer);
    index = 0;
    if (HttpQueryInfoA(hUrl, HTTP_QUERY_ACCEPT_RANGES, buffer, &bufferLen, &index)) {
        std::string ranges(buffer);
        supportsRange = (ranges.find("bytes") != std::string::npos);
    } else {
        supportsRange = (fileSize > 0);
    }

    InternetCloseHandle(hUrl);
    InternetCloseHandle(hInternet);
    return true;
}

